 * conventional order, so `mod+shift+d` renders as `⇧⌘ D` on Apple platforms and
 * `Ctrl Shift D` elsewhere.
 *
 * @example
 * ```js
 * const { label, aria } = formatShortcut("mod+b");
 * // Apple:  label "⌘ B",   aria "Command+B"
 * // Others: label "Ctrl B", aria "Ctrl+B"
 * ```
