        const safeLinkUrl = linkUrl.replace(/%(?![0-9A-Fa-f]{2})/g, "%25");
        const parsed = new URL(safeLinkUrl, window.location.origin);
        linkUrl = parsed.toString();

        // new URL("https://example.com").toString() -> https://example.com/
        if (
          linkUrl.endsWith("/") &&
